insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$cananeia$q$, $q$https://camaracananeia.sp.gov.br/?pag=T0dRPU9EZz1PR009T1RnPQ&id=2035&idtipolei=1 (Lei 1.680/2004)$q$, $q$Ato oficial de Cananéia: domínio público (Lei 9.610/1998 art. 8º IV). Geometria da via: OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 2, $q$Lei 1.680/2004 (promulgada pela Câmara após veto): proíbe o tráfego de caminhões na via de passagem ao lado do Hotel Marazul. O ato não nomeia a via: a geometria é aproximada, por proximidade ao hotel no OSM. As leis de ônibus de turismo (1.092/1997 e outras) não são de caminhões.$q$);
